DIRS = 'NESW'                      # clockwise, so R = +1, L = -1
STEP = {'N': (0, 1), 'E': (1, 0), 'S': (0, -1), 'W': (-1, 0)}

def solution(spec):
    lines = [ln.strip() for ln in spec.strip().split('\n') if ln.strip()]
    # line 0 is the plateau corner; the classic version never leaves it
    out = []
    for i in range(1, len(lines), 2):
        x, y, d = lines[i].split()
        x, y = int(x), int(y)
        for c in lines[i + 1] if i + 1 < len(lines) else '':
            if c == 'L':
                d = DIRS[(DIRS.index(d) - 1) % 4]
            elif c == 'R':
                d = DIRS[(DIRS.index(d) + 1) % 4]
            elif c == 'M':
                dx, dy = STEP[d]
                x, y = x + dx, y + dy
        out.append(f'{x} {y} {d}')
    return '\n'.join(out)

