def solution(spec):
    # Straightforward version: track the heading as an angle and use if/elif for each move
    lines = [ln.strip() for ln in spec.strip().split('\n') if ln.strip()]
    result = []
    for i in range(1, len(lines), 2):
        x, y, d = lines[i].split()
        x, y = int(x), int(y)
        angle = {'N': 90, 'E': 0, 'S': 270, 'W': 180}[d]
        cmds = lines[i + 1] if i + 1 < len(lines) else ''
        for c in cmds:
            if c == 'L':
                angle = (angle + 90) % 360
            elif c == 'R':
                angle = (angle - 90) % 360
            elif c == 'M':
                if angle == 0: x += 1
                elif angle == 90: y += 1
                elif angle == 180: x -= 1
                else: y -= 1
        result.append(str(x) + ' ' + str(y) + ' ' + {90: 'N', 0: 'E', 270: 'S', 180: 'W'}[angle])
    return '\n'.join(result)
